export function localizedProductData(locale: SupportedLocale, source: Product): Product {
  if (locale === "nl") return source;
  const identity = identities[locale]?.[source.slug] ?? source;
  const pack = packs[locale];
  return {
    ...source,
    ...identity,
    problems: pack.problems.map(([title,text]) => ({ title, text })),
    workflow: pack.workflow.map(([label,title,output]) => ({ label, title, text:title, output })),
    core: pack.core.map(([title,text]) => ({ title, text })),
    boundaries: pack.boundaries.map(([title,text]) => ({ title, text })),
    fit: pack.fit.map(([title,text]) => ({ title, text })),
    faq: pack.faq.map(([question,answer]) => ({ question, answer })),
    calculator: { volumeLabel:pack.calc[0], minutesLabel:pack.calc[1], automationLabel:pack.calc[2], outputLabel:pack.calc[3] },
    seoTitle:`${identity.name} | Autopilots`,
    metaDescription:identity.intro,
  };
}

